"""expand_copy: materialize a broadcast expanded view into a new dense tensor.

out = new C-contiguous tensor of shape `size`, out[i] = self_storage[sum_k i_k*es_k]
where es is the expanded stride vector (0 for broadcast dims).

Host side only performs metadata/stride math; every element is written by a
Triton kernel.  The dispatch is chosen from the *collapsed* (stride, len) pairs
of the expanded view so the kernels stay linear (no per-element div/mod):

  collapsed rank 1, stride 1  -> flat copy
  collapsed rank 1, stride 0  -> fill (single scalar splat)
  collapsed rank 2            -> row copy / row-replicate / row-splat
  collapsed rank >= 3         -> generic gather fallback

The resolved plan (output shape/dtype/device, grid and kernel constants) is
memoized on the call metadata, so repeated identical calls only pay one
`torch.empty` plus one kernel launch.  No tensor values, intermediates or
results are cached: every call re-reads the current input storage.
"""

import torch
import triton
import triton.language as tl

# ------------------------------------------------------- kernels (hot paths)


@triton.jit
def _copy_even(src, dst, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    tl.store(dst + offs, tl.load(src + offs))


@triton.jit
def _copy_mask(src, dst, n, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    m = offs < n
    tl.store(dst + offs, tl.load(src + offs, mask=m), mask=m)


@triton.jit
def _fill_even(src, dst, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    tl.store(dst + offs, tl.load(src))


@triton.jit
def _fill_mask(src, dst, n, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    tl.store(dst + offs, tl.load(src), mask=offs < n)


# ------------------------------------------------- kernels (broadcast paths)


@triton.jit
def _row_copy(
    src,
    dst,
    L,
    so,
    si,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
    MODE: tl.constexpr,
    I64: tl.constexpr,
):
    # MODE 1: si == 1 (contiguous inner), 0: si == 0 (splat), 2: general si
    pid = tl.program_id(0)
    rid = tl.program_id(1)
    if I64:
        rid = rid.to(tl.int64)
        cols = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    else:
        cols = pid * BLOCK + tl.arange(0, BLOCK)
    sbase = rid * so
    dbase = rid * L
    if MODE == 1:
        if EVEN:
            tl.store(dst + dbase + cols, tl.load(src + sbase + cols))
        else:
            m = cols < L
            tl.store(dst + dbase + cols, tl.load(src + sbase + cols, mask=m), mask=m)
    elif MODE == 0:
        v = tl.load(src + sbase)
        if EVEN:
            tl.store(dst + dbase + cols, v)
        else:
            m = cols < L
            tl.store(dst + dbase + cols, v, mask=m)
    else:
        if EVEN:
            tl.store(dst + dbase + cols, tl.load(src + sbase + cols * si))
        else:
            m = cols < L
            tl.store(
                dst + dbase + cols, tl.load(src + sbase + cols * si, mask=m), mask=m
            )


@triton.jit
def _repl_copy(
    src, dst, rows, L, BLOCK: tl.constexpr, EVEN: tl.constexpr, I64: tl.constexpr
):
    # every row shares one source row (outer stride == 0)
    pid = tl.program_id(0)
    if I64:
        cols = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    else:
        cols = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        v = tl.load(src + cols)
        for r in tl.range(0, rows):
            tl.store(dst + r * L + cols, v)
    else:
        m = cols < L
        v = tl.load(src + cols, mask=m)
        for r in tl.range(0, rows):
            tl.store(dst + r * L + cols, v, mask=m)


@triton.jit
def _splat_flat(
    src, dst, n, so, L: tl.constexpr, BLOCK: tl.constexpr, EVEN: tl.constexpr
):
    # broadcast innermost dim: dense dst, one source element per L outputs
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        tl.store(dst + offs, tl.load(src + (offs // L) * so))
    else:
        m = offs < n
        tl.store(dst + offs, tl.load(src + (offs // L) * so, mask=m), mask=m)


@triton.jit
def _nd_copy(
    src,
    dst,
    n,
    l0,
    s0,
    l1,
    s1,
    l2,
    s2,
    l3,
    s3,
    l4,
    s4,
    l5,
    s5,
    l6,
    s6,
    l7,
    s7,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
):
    # generic fallback: vector index decomposition (innermost pair first)
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < n
    rem = offs.to(tl.int64)
    off = tl.zeros_like(rem)
    off += (rem % l0) * s0
    rem = rem // l0
    off += (rem % l1) * s1
    rem = rem // l1
    off += (rem % l2) * s2
    rem = rem // l2
    off += (rem % l3) * s3
    rem = rem // l3
    off += (rem % l4) * s4
    rem = rem // l4
    off += (rem % l5) * s5
    rem = rem // l5
    off += (rem % l6) * s6
    rem = rem // l6
    off += (rem % l7) * s7
    if EVEN:
        tl.store(dst + offs, tl.load(src + off))
    else:
        tl.store(dst + offs, tl.load(src + off, mask=m), mask=m)


# ---------------------------------------------------------------- host side

_I32MAX = 0x7FFFFFFF
_MEMO = None


def _next_pow2(v):
    return 1 << (v - 1).bit_length()


def _plan(x, size):
    """Resolve the launch plan for this call metadata (no tensor values read)."""
    nd = len(size)
    xs = x.shape
    lead = nd - x.dim()
    if lead < 0:
        x.expand(size)  # canonical RuntimeError
        raise RuntimeError("expand_copy: size rank smaller than tensor rank")

    st = x.stride()
    cs = []  # collapsed strides, innermost first
    cl = []  # collapsed lengths, innermost first
    neg = False
    for k in range(nd - 1, -1, -1):
        t = size[k]
        j = k - lead
        if j < 0:
            t = int(t)
            s = 0
        else:
            t = int(t)
            dj = xs[j]
            if t == -1:
                t = dj
                neg = True
            if dj == t:
                s = st[j]
            elif dj == 1:
                s = 0
            else:
                x.expand(size)  # canonical RuntimeError
                raise RuntimeError("expand_copy: incompatible size")
        if t == 0:
            return (8, size, x.dtype, x.device)
        if t == 1:
            continue
        if cl:
            if cs[-1] * cl[-1] == s or (s == 0 and cs[-1] == 0):
                cl[-1] *= t
                continue
        cs.append(s)
        cl.append(t)

    if neg:
        sz = []
        for k, t in enumerate(size):
            t = int(t)
            if t == -1:
                t = xs[k - lead] if k >= lead else 1
            sz.append(t)
        sz = tuple(sz)
    else:
        sz = size if type(size) is tuple else tuple(size)

    n = 1
    for v in cl:
        n *= v
    dt, dev = x.dtype, x.device
    if n == 0:
        return (8, sz, dt, dev)

    r = len(cs)
    i64 = n > _I32MAX
    if r == 0:
        si, L = 1, 1
    else:
        si, L = cs[0], cl[0]

    if r <= 1:
        if si == 1:
            if i64:
                BLOCK = 4096
                return (
                    4,
                    sz,
                    dt,
                    dev,
                    ((n + BLOCK - 1) // BLOCK, 1),
                    L,
                    0,
                    si,
                    BLOCK,
                    (L % BLOCK == 0),
                    1,
                    True,
                )
            if n >= 65536:
                BLOCK = 4096
            elif n >= 1024:
                BLOCK = 1024
            else:
                BLOCK = max(16, _next_pow2(n))
            if n % BLOCK == 0:
                return (0, sz, dt, dev, (n // BLOCK,), BLOCK)
            return (1, sz, dt, dev, ((n + BLOCK - 1) // BLOCK,), n, BLOCK)
        if si == 0:
            if i64:
                BLOCK = 4096
                return (
                    4,
                    sz,
                    dt,
                    dev,
                    ((n + BLOCK - 1) // BLOCK, 1),
                    L,
                    0,
                    0,
                    BLOCK,
                    (L % BLOCK == 0),
                    0,
                    True,
                )
            if n >= 65536:
                BLOCK = 4096
            elif n >= 1024:
                BLOCK = 1024
            else:
                BLOCK = max(16, _next_pow2(n))
            if n % BLOCK == 0:
                return (2, sz, dt, dev, (n // BLOCK,), BLOCK)
            return (3, sz, dt, dev, ((n + BLOCK - 1) // BLOCK,), n, BLOCK)
        BLOCK = 4096 if L >= 4096 else max(32, _next_pow2(L))
        return (
            4,
            sz,
            dt,
            dev,
            ((L + BLOCK - 1) // BLOCK, 1),
            L,
            0,
            si,
            BLOCK,
            (L % BLOCK == 0),
            2,
            i64,
        )

    if r == 2:
        so, rows = cs[1], cl[1]
        if so == 0:
            BLOCK = 4096 if L >= 4096 else max(32, _next_pow2(L))
            return (
                5,
                sz,
                dt,
                dev,
                ((L + BLOCK - 1) // BLOCK,),
                rows,
                L,
                BLOCK,
                (L % BLOCK == 0),
                i64,
            )
        if si == 0:
            if L >= 32:
                BLOCK = 4096 if L >= 4096 else max(32, _next_pow2(L))
                return (
                    4,
                    sz,
                    dt,
                    dev,
                    ((L + BLOCK - 1) // BLOCK, rows),
                    L,
                    so,
                    0,
                    BLOCK,
                    (L % BLOCK == 0),
                    0,
                    i64,
                )
            BLOCK = 4096 if n >= 4096 else max(32, _next_pow2(n))
            return (
                6,
                sz,
                dt,
                dev,
                ((n + BLOCK - 1) // BLOCK,),
                n,
                so,
                L,
                BLOCK,
                (n % BLOCK == 0),
            )
        BLOCK = 4096 if L >= 4096 else max(32, _next_pow2(L))
        return (
            4,
            sz,
            dt,
            dev,
            ((L + BLOCK - 1) // BLOCK, rows),
            L,
            so,
            si,
            BLOCK,
            (L % BLOCK == 0),
            1 if si == 1 else 2,
            i64,
        )

    # generic fallback: pad to 8 collapsed pairs (len 1, stride 0 is a no-op)
    pad = 8 - r
    lens = [1] * pad + cl
    strs = [0] * pad + cs
    BLOCK = 4096 if n >= 4096 else max(32, _next_pow2(n))
    return (
        7,
        sz,
        dt,
        dev,
        ((n + BLOCK - 1) // BLOCK,),
        n,
        lens[0],
        strs[0],
        lens[1],
        strs[1],
        lens[2],
        strs[2],
        lens[3],
        strs[3],
        lens[4],
        strs[4],
        lens[5],
        strs[5],
        lens[6],
        strs[6],
        lens[7],
        strs[7],
        BLOCK,
        (n % BLOCK == 0),
    )


def expand_copy(x, size, *, implicit=False):
    global _MEMO
    key = (x.shape, x.stride(), size, x.dtype, x.device)
    m = _MEMO
    if m is not None and m[0] == key:
        p = m[1]
    else:
        p = _plan(x, size)
        _MEMO = (key, p)

    k = p[0]
    out = torch.empty(p[1], dtype=p[2], device=p[3])
    if k == 0:
        _copy_even[p[4]](x, out, p[5])
    elif k == 1:
        _copy_mask[p[4]](x, out, p[5], p[6])
    elif k == 2:
        _fill_even[p[4]](x, out, p[5])
    elif k == 3:
        _fill_mask[p[4]](x, out, p[5], p[6])
    elif k == 4:
        _row_copy[p[4]](x, out, p[5], p[6], p[7], p[8], p[9], p[10], p[11])
    elif k == 5:
        _repl_copy[p[4]](x, out, p[5], p[6], p[7], p[8], p[9])
    elif k == 6:
        _splat_flat[p[4]](x, out, p[5], p[6], p[7], p[8], p[9])
    elif k == 7:
        _nd_copy[p[4]](
            x,
            out,
            p[5],
            p[6],
            p[7],
            p[8],
            p[9],
            p[10],
            p[11],
            p[12],
            p[13],
            p[14],
            p[15],
            p[16],
            p[17],
            p[18],
            p[19],
            p[20],
            p[21],
            p[22],
        )
    return out
